SubProceso SumaVector(datos[] Como Entero Por Referencia, indice Como Entero, tamano Como Entero) Como Entero
    Si indice >= tamano Entonces
        Retornar 0;
    SiNo
        Retornar datos[indice] + SumaVector(datos, indice + 1, tamano);
    FinSi
FinSubProceso

Proceso EjecutarSumaVector
    Dimension vector[5] Como Entero;
    Leer vector[0];
    Leer vector[1];
    Leer vector[2];
    Leer vector[3];
    Leer vector[4];
    Escribir SumaVector(vector, 0, 5);
FinProceso
